/* ink.js: penne, pennarelli, evidenziatori, gomma e testo sulle pagine del PDF */
const INK={u:[],r:[],cancel:null};
const INKW={pen:[.8,1.4,2.4,4],mk:[2.2,3.5,5.5,8],hl:[9,14,20,28]},INKR=[6,10,16,24],INKT=[10,14,20,28],INKK={pen:'p',mk:'m',hl:'h',er:'e',tx:'t'};
const PENC=['#1b1b1f','#e8334a','#f08a24','#16a34a','#2563eb','#7c3aed','#ffffff'],HLC=['#ffd233','#7ff7a6','#7fd6ff','#ffadb8','#ffc4a3','#c7b3ff'];
const inkDef=()=>({on:false,k:'pen',pz:1,mz:1,hz:2,ez:1,tz:1,pc:'#1b1b1f',mc:'#e8334a',hc:'#ffd233',tc:'#1b1b1f',fin:false});
function drawItem(g,s){if(s.k=='tx'){g.save();g.font=`${s.sz}px Inter,sans-serif`;g.fillStyle=s.c;g.textBaseline='top';s.t.split('\n').forEach((ln,i)=>g.fillText(ln,s.x,s.y+i*s.sz*1.25));g.restore();return}
 const P=s.p;if(!P||!P.length)return;g.save();g.lineCap=s.k=='hl'?'square':'round';g.lineJoin='round';g.strokeStyle=s.c;g.lineWidth=s.w;if(s.k=='hl')g.globalAlpha=.38;g.beginPath();g.moveTo(P[0][0],P[0][1]);
 if(P.length==1)g.lineTo(P[0][0]+.01,P[0][1]);else{for(let i=1;i<P.length-1;i++){const mx=(P[i][0]+P[i+1][0])/2,my=(P[i][1]+P[i+1][1])/2;g.quadraticCurveTo(P[i][0],P[i][1],mx,my)}g.lineTo(P[P.length-1][0],P[P.length-1][1])}g.stroke();g.restore()}
function paintInk(n,live){const w=PV.shells&&PV.shells[n],cv=w&&w.querySelector('.ik'),d=doc();if(!cv||!d||!PM)return;const sc=PV.scale,pm=PM.pages[n],k=Math.min(2,devicePixelRatio||1),W=Math.round(pm.w*sc*k),H=Math.round(pm.h*sc*k);
 cv.width=W;cv.height=H;const g=cv.getContext('2d');g.scale(sc*k,sc*k);((d.ink&&d.ink[n])||[]).forEach(s=>drawItem(g,s));if(live)drawItem(g,live)}
const inkPush=op=>{INK.u.push(op);INK.r=[]};
function inkUndo(){const op=INK.u.pop();if(!op)return;const d=doc(),L=(d.ink=d.ink||{})[op.n]=(d.ink[op.n]||[]);if(op.t=='add'){const i=L.findIndex(s=>s.id==op.s.id);if(i>=0)L.splice(i,1)}else L.splice(Math.min(op.i,L.length),0,op.s);INK.r.push(op);d.mod=Date.now();save();paintInk(op.n);render()}
function inkRedo(){const op=INK.r.pop();if(!op)return;const d=doc(),L=(d.ink=d.ink||{})[op.n]=(d.ink[op.n]||[]);if(op.t=='add')L.push(op.s);else{const i=L.findIndex(s=>s.id==op.s.id);if(i>=0)L.splice(i,1)}INK.u.push(op);d.mod=Date.now();save();paintInk(op.n);render()}
const dseg=(p,a,b)=>{const dx=b[0]-a[0],dy=b[1]-a[1],l=dx*dx+dy*dy;let t=l?((p.x-a[0])*dx+(p.y-a[1])*dy)/l:0;t=Math.max(0,Math.min(1,t));return Math.hypot(p.x-(a[0]+t*dx),p.y-(a[1]+t*dy))};
const txBox=s=>{const ls=s.t.split('\n');return{x:s.x,y:s.y,w:Math.max(...ls.map(l=>l.length))*s.sz*.6,h:ls.length*s.sz*1.25}};
function hitItem(s,p,r){if(s.k=='tx'){const b=txBox(s);return p.x>=b.x-r&&p.x<=b.x+b.w+r&&p.y>=b.y-r&&p.y<=b.y+b.h+r}return s.p.some((q,i)=>Math.hypot(q[0]-p.x,q[1]-p.y)<r+s.w/2||(s.p[i+1]&&dseg(p,q,s.p[i+1])<r+s.w/2))}
function eraseAt(p){const d=doc(),L=(d.ink&&d.ink[p.n])||[],r=INKR[S.ink.ez];const hit=L.filter(s=>hitItem(s,p,r));if(!hit.length)return;hit.forEach(s=>{const i=L.indexOf(s);L.splice(i,1);inkPush({t:'del',n:p.n,s,i})});d.mod=Date.now();save();paintInk(p.n);render()}
async function textAt(p){const d=doc(),L=((d.ink=d.ink||{})[p.n]=(d.ink[p.n]||[])),ex=L.find(s=>s.k=='tx'&&hitItem(s,p,2)),r=await form(ex?'Modifica il testo':'Aggiungi testo',[{l:'Testo (vuoto per eliminare)',v:ex?ex.t:'',rows:3}],ex?'Salva':'Aggiungi');if(!r)return;const t=r[0].trim();
 if(ex){const i=L.indexOf(ex);if(!t){L.splice(i,1);inkPush({t:'del',n:p.n,s:ex,i})}else ex.t=t}else if(t){const s={id:Date.now()+Math.random(),k:'tx',x:+p.x.toFixed(1),y:+p.y.toFixed(1),t,sz:INKT[S.ink.tz],c:S.ink.tc};L.push(s);inkPush({t:'add',n:p.n,s})}d.mod=Date.now();save();paintInk(p.n);render()}
function inkBind(el){let CUR=null,ER=false,PAN=null;INK.cancel=()=>{CUR=null;ER=false;PAN=null};
 const pos=e=>{const w=e.target.closest&&e.target.closest('.pgw');if(!w||!PV.scale)return null;const r=w.getBoundingClientRect();return{n:+w.dataset.pg,x:(e.clientX-r.left)/PV.scale,y:(e.clientY-r.top)/PV.scale}};
 el.addEventListener('pointerdown',e=>{const I_=S.ink;if(!I_||!I_.on)return;if(e.pointerType=='touch'&&e.isPrimary===false){INK.cancel();return}const draws=e.pointerType!='touch'||I_.fin;if(!draws){PAN={x:e.clientX,y:e.clientY};return}
  const p=pos(e);if(!p||e.button>0)return;e.preventDefault();if(I_.k=='er'){ER=true;eraseAt(p);return}if(I_.k=='tx'){textAt(p);return}
  const kk=INKK[I_.k];CUR={n:p.n,s:{id:Date.now()+Math.random(),k:I_.k,c:I_[kk+'c'],w:INKW[I_.k][I_[kk+'z']],p:[[+p.x.toFixed(1),+p.y.toFixed(1)]]}};try{el.setPointerCapture(e.pointerId)}catch(x){}paintInk(p.n,CUR.s)});
 el.addEventListener('pointermove',e=>{if(PAN&&e.pointerType=='touch'){el.scrollTop-=e.clientY-PAN.y;el.scrollLeft-=e.clientX-PAN.x;PAN.x=e.clientX;PAN.y=e.clientY;return}
  if(ER){const p=pos(e);if(p)eraseAt(p);return}if(!CUR)return;const evs=e.getCoalescedEvents?e.getCoalescedEvents():[e],w=PV.shells[CUR.n].getBoundingClientRect();
  for(const q of evs){const x=(q.clientX-w.left)/PV.scale,y=(q.clientY-w.top)/PV.scale,L=CUR.s.p[CUR.s.p.length-1];if(Math.hypot(x-L[0],y-L[1])>.3)CUR.s.p.push([+x.toFixed(1),+y.toFixed(1)])}paintInk(CUR.n,CUR.s)});
 const up=()=>{PAN=null;ER=false;if(!CUR)return;const c=CUR;CUR=null;const d=doc();((d.ink=d.ink||{})[c.n]=(d.ink[c.n]||[])).push(c.s);inkPush({t:'add',n:c.n,s:c.s});d.mod=Date.now();save();paintInk(c.n);render()};
 el.addEventListener('pointerup',up);el.addEventListener('pointercancel',()=>INK.cancel())}
function inkBar(){const I_=S.ink;if(!I_||!I_.on||S.view!='read')return'';const k=I_.k,kk=INKK[k],z=I_[kk+'z'],tools=[['pen','pen-tool','Penna'],['mk','pencil','Pennarello'],['hl','highlighter','Evidenziatore'],['er','eraser','Gomma'],['tx','type','Testo']];
 const dots=[0,1,2,3].map(i=>{const px=[7,10,14,18][i];return`<i class="szd${i==z?' on':''}" style="width:${px}px;height:${px}px" onclick="inkSize(${i})"></i>`}).join(''),pal=k=='er'?'':(k=='hl'?HLC:PENC).map(c=>`<i class="inkc${c==I_[kk+'c']?' on':''}" style="background:${c}" onclick="inkColor('${c}')"></i>`).join('');
 return`<div class=inkbar><div class=ib1>${tools.map(([t,ic,l])=>`<button class="${k==t?'on':''}" title="${l}" onclick="inkTool('${t}')">${I(ic)}</button>`).join('')}<span class=sp></span><button title="Annulla" onclick="inkUndo()" ${INK.u.length?'':'disabled'}>${I('undo-2')}</button><button title="Ripeti" onclick="inkRedo()" ${INK.r.length?'':'disabled'}>${I('redo-2')}</button><button class="${I_.fin?'on':''}" title="Disegna con il dito" onclick="inkFin()">${I('hand')}</button><button title="Chiudi" onclick="inkClose()">${I('x')}</button></div><div class=ib2><span class=szg>${dots}</span>${pal}</div></div>`}
const inkTool=k=>{S.ink.k=k;render()},inkSize=i=>{S.ink[INKK[S.ink.k]+'z']=i;render()},inkColor=c=>{S.ink[INKK[S.ink.k]+'c']=c;render()},inkFin=()=>{S.ink.fin=!S.ink.fin;render()},inkClose=()=>{S.ink.on=false;S.tool=null;render()};
function inkOpen(){const d=doc();S.menu=null;if(!d||d.kind!='pdf'||S.pdfText||!PV.scale){render();return tell('Le penne funzionano sui PDF visti a pagine.')}S.ink=Object.assign(inkDef(),S.ink||{},{on:true});S.tool='ink';S.panel=null;clearSel();render()}
